// Merge Sorted Array - Merge arr2 into arr1 in sorted order
var array1 = AnimatedArray<Int>()
var array2 = AnimatedArray<Int>()
array1.append(1)
array1.append(3)
array1.append(5)
array2.append(2)
array2.append(4)
array2.append(6)

func mergeSorted(arr1: inout AnimatedArray<Int>, arr2: inout AnimatedArray<Int>) {
    for j in 0..<arr2.count {
        guard let val = arr2.at(j) else { continue }
        var insertPos = arr1.count
        for i in 0..<arr1.count {
            if let current = arr1.at(i), current > val {
                insertPos = i
                break
            }
        }
        arr1.insert(val, at: insertPos)
    }
}

mergeSorted(arr1: &array1, arr2: &array2)
